# Désactivation sûre des services télémétrie
$servicesToDisable = @(
    "DiagTrack",          # Connected User Experiences and Telemetry
    "dmwappushservice",   # Notifications push
    "CompatTelRunner"     # Rapport compatibilité
)

foreach ($svc in $servicesToDisable) {
    if (Get-Service -Name $svc -ErrorAction SilentlyContinue) {
        Stop-Service -Name $svc -Force
        Set-Service -Name $svc -StartupType Disabled
    }
}

# Niveau télémétrie minimal (0 = Sécurité minimale)
New-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" `
                 -Name "AllowTelemetry" -Value 0 -PropertyType DWord -Force

# =======================================================
# Script PowerShell d'installation 7Zip, VLC, LibreOffice
# =======================================================

function Install-7Zip {
    $found = Get-ChildItem -Path (Get-PSDrive -PSProvider FileSystem).Root -Recurse -Filter '7z*-x64.exe' -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($found) { Start-Process -FilePath $found.FullName -ArgumentList '/S /D="C:\Program Files\7-Zip"' -Wait } 
    else { Write-Warning "7-Zip non trouvé." }
}

function Install-VLC {
    $found = Get-ChildItem -Path (Get-PSDrive -PSProvider FileSystem).Root -Recurse -Filter 'vlc*-win64.exe' -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($found) { Start-Process -FilePath $found.FullName -ArgumentList '/L=1036 /S /NCRC /D="C:\Program Files\VideoLAN\VLC"' -Wait } 
    else { Write-Warning "VLC non trouvé." }
}

function Install-LibreOffice {
    $found = Get-ChildItem -Path (Get-PSDrive -PSProvider FileSystem).Root -Recurse -Filter 'LibreOffice*.msi' -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($found) { Start-Process "msiexec.exe" -ArgumentList "/i `"$($found.FullName)`" /quiet /norestart" -Wait } 
    else { Write-Warning "LibreOffice non trouvé." }
}

Install-7Zip
Install-VLC
Install-LibreOffice

# =============================================================
# Script PowerShell de téléchargement et d'installation Firefox
# =============================================================

$timeout = [datetime]::Now.AddMinutes(5)
$exe = "$env:LOCALAPPDATA\Microsoft\WindowsApps\winget.exe"

while ($true) {
    if (Test-Path $exe) {
        Write-Host "Winget trouvé. Installation de Firefox (version française)..."
        & $exe install --exact --id Mozilla.Firefox `
            --silent --accept-package-agreements --accept-source-agreements `
            --source winget --scope machine --locale fr-FR
        Write-Host "Installation de Firefox terminée."
        return
    }

    if ([datetime]::Now -gt $timeout) {
        Write-Warning ("File {0} does not exist." -f $exe)
        return
    }

    Start-Sleep -Seconds 1
}

